  j constant jsonb := $capuchino$[{"id":"f1ba021c-866e-4b37-a577-485a64b44ae9","recipe_group_id":"cc320b67-294e-4420-b904-4bd3d12d4c1b","language":"es","slug":"receta-de-capuchino","public_path":"/receta-de-capuchino","source_url":"https://manualdecocina.com/receta-de-capuchino/","title":"Capuchino casero con espresso y leche","excerpt":"Un capuchino sin azúcar añadida con 36 g de espresso y 120 g de leche entera, espuma fina y control de la temperatura.","summary":"Este capuchino combina un espresso recién preparado con leche entera pasteurizada y una capa de espuma fina. No lleva cacao, chocolate, nata ni azúcar añadida; los azúcares del cálculo proceden principalmente de la leche. Se necesita una cafetera de espresso y una lanza de vapor apta para pequeñas cantidades, una jarra y un termómetro.\n\nLa propuesta rinde una taza de unos 180–200 ml según el aire incorporado. Se estiman 5 minutos de preparación y 5 para preparar el café y calentar la leche, 10 en total una vez que la máquina está lista. El precalentamiento de cada cafetera puede añadir tiempo. Cantidades, tiempos y volumen final están pendientes de prueba de cocina; no se afirma una proporción tradicional universal de tres partes iguales.","category":"Bebidas","category_slug":"bebidas","difficulty":"Media","course":"Bebida","cuisine":"Italiana, propuesta casera","prep_time_minutes":5,"cook_time_minutes":5,"total_time_minutes":10,"servings":1,"keywords":["capuchino","cappuccino casero","espresso con leche","espuma de leche"],"ingredients":[{"name":"espresso recién preparado","amount":"36","unit":"g de bebida, no de café molido","group":"Café"},{"name":"leche entera pasteurizada fría","amount":"120","unit":"g","group":"Leche"}],"steps":[{"title":"Prepara la taza, la jarra y la leche","content":"Usa una taza de 180–200 ml, una jarra de vapor pequeña compatible con la cantidad de leche y un termómetro limpio. Precalienta la taza con agua caliente y vacíala completamente. Pesa los 120 g de leche fría a 4 °C o menos en la jarra; no la dejes esperar a temperatura ambiente. Sigue el manual de tu máquina para su precalentamiento y purga.","image_alt":"Jarra metálica con leche fría junto a una taza vacía y una cafetera","image_url":"/recetas/receta-de-capuchino/paso-01.webp"},{"title":"Prepara y pesa el espresso","content":"Prepara café espresso en la taza caliente y pesa 36 g de bebida recién extraída, sin contar el peso de la taza. Si tu cafetera no permite extracción y vapor a la vez, sigue la secuencia de su manual y evita dejar el café mucho tiempo. El peso indicado es de líquido preparado, no de café seco. No añadas azúcar ni cacao en esta versión.","image_alt":"Espresso recién extraído en una taza bajo el portafiltro","image_url":"/recetas/receta-de-capuchino/paso-02.webp"},{"title":"Texturiza la leche sin hervir","content":"Purga brevemente la lanza apuntando a la bandeja y sin acercar las manos al vapor. Introduce la punta cerca de la superficie de los 120 g de leche y abre el vapor para incorporar aire con un siseo suave, no grandes burbujas. Sumerge un poco la punta para formar un remolino y detén el vapor cuando el termómetro marque 55–60 °C. Cierra el vapor antes de retirar la jarra. No hiervas ni calientes solo por un tiempo fijo; la potencia de cada máquina cambia.","image_alt":"Lanza de vapor texturizando leche en una jarra metálica","image_url":"/recetas/receta-de-capuchino/paso-03.webp"},{"title":"Integra la espuma y limpia la lanza","content":"Limpia enseguida la lanza con un paño limpio destinado a ella y purga según el manual, evitando quemaduras. Da un golpe suave a la base de la jarra sobre un paño y mueve la leche en círculos para unir espuma y líquido. Debe verse brillante y fluida, sin una capa de burbujas grandes separada. No vuelvas a vaporizar leche que ya se ha calentado.","image_alt":"Leche texturizada brillante en una jarra tras girarla suavemente","image_url":"/recetas/receta-de-capuchino/paso-04.webp"},{"title":"Vierte y sirve de inmediato","content":"Vierte la leche sobre los 36 g de espresso con un hilo continuo y acerca la jarra al final para depositar la espuma fina. Utiliza toda la leche medida para mantener la estimación; no hace falta dibujar una figura. Sirve enseguida y comprueba que la taza no queme. El volumen propuesto de 180–200 ml depende de la espuma. Esta bebida no se guarda para recalentar: desecha la leche texturizada sobrante y conserva la leche sin usar en frío.","image_alt":"Capuchino terminado con espuma fina en una taza de cerámica","image_url":"/recetas/receta-de-capuchino/paso-05.webp"}],"notes":"Contiene leche y cafeína. Para el espresso puedes usar como punto de partida 18 g de café molido y obtener 36 g de bebida, relación 1:2, en unos 25–35 segundos; ajusta molienda y receta a tu equipo. Esa preparación sustituye al ingrediente espresso listo, no se suma a él, y los posos no se ingieren ni se cuentan como 18 g de café comestible. Usa la dosis adecuada a la cesta de tu máquina y sigue su manual. Si la jarra o lanza requiere más leche que 120 g, el equipo no es apropiado para esta formulación de una taza; no calientes de nuevo el sobrante. La leche sin lactosa puede espumar, pero su perfil nutricional cambia. Una bebida vegetal modifica espuma, sabor y nutrientes y requiere otra ficha; esta no se presenta como vegana. No se incluyen azúcar, cacao ni canela opcionales en los ingredientes o cálculo. No prometemos un contenido exacto de cafeína: depende de variedad, dosis y extracción. Mantén la leche fría y usa solo pasteurizada. El vapor y la taza pueden quemar; no dejes que el termómetro toque la lanza caliente.","nutrition":{"fiber_g":0,"sodium_mg":57,"saturated_fat_g":2.3,"fat_g":4,"protein_g":3.8,"sugar_g":6.1,"carbs_g":6.4,"calories":76.4,"estimated":true,"serving_size":"1 taza propuesta, toda la leche medida","source":"USDA FoodData Central — SR Legacy, abril de 2018","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Dos fichas USDA verificadas por FDC ID en el archivo oficial: 36 g de espresso preparado y 120 g de leche entera. Una ración; no se cuentan posos de café, agua de precalentar la taza ni aire incorporado. Se supone que toda la leche medida se vierte en la taza.","note":"Estimación, no análisis de la bebida. Leche real, extracción y líquido que quede en la jarra cambian el resultado; el volumen, los tiempos y el rendimiento esperan prueba de cocina. No incluye azúcar añadida ni cálculo de cafeína.","inputs":[{"fdc_id":171891,"fdc_description":"Beverages, coffee, brewed, espresso, restaurant-prepared","per_100g":{"fiber_g":0,"sodium_mg":14,"saturated_fat_g":0.092,"fat_g":0.18,"protein_g":0.12,"sugar_g":0,"carbs_g":1.67,"calories":9},"source_url":"https://fdc.nal.usda.gov/food-details/171891/nutrients","ingredient":"espresso preparado","edible_grams":36},{"fdc_id":171265,"fdc_description":"Milk, whole, 3.25% milkfat, with added vitamin D","per_100g":{"fat_g":3.25,"sugar_g":5.05,"carbs_g":4.8,"calories":61,"saturated_fat_g":1.86,"fiber_g":0,"sodium_mg":43,"protein_g":3.15},"source_url":"https://fdc.nal.usda.gov/food-details/171265/nutrients","ingredient":"leche entera pasteurizada","edible_grams":120}]},"image_url":"/recetas/receta-de-capuchino/portada.webp","gallery":[{"url":"/recetas/receta-de-capuchino/portada.webp","alt":"Capuchino casero con espuma fina y crema de espresso en taza"}],"seo":{"title":"Capuchino casero con espresso: paso a paso | Manual de Cocina","description":"Capuchino sin azúcar añadida con espresso y leche medida. Texturiza a 55–60 °C y sirve con espuma fina; receta propuesta para una taza.","image_alt":"Capuchino casero con espuma fina y crema de espresso en taza","image_variants":["/recetas/receta-de-capuchino/portada-1x1.webp","/recetas/receta-de-capuchino/portada-4x3.webp","/recetas/receta-de-capuchino/portada-16x9.webp"],"faq":[{"q":"¿Por qué aparecen 36 g de espresso y no 36 g de café molido?","a":"Son el peso de la bebida ya preparada. Como punto de partida se pueden usar 18 g de café seco para obtener 36 g de espresso, relación 1:2. Los posos se desechan; no se añaden a la taza ni al cálculo nutricional."},{"q":"¿Por qué la espuma queda con burbujas grandes?","a":"Suele entrar demasiado aire o la punta queda demasiado alta. Incorpora aire suavemente al principio y forma después un remolino; gira la jarra al terminar. Detén el calentamiento a 55–60 °C y no vuelvas a vaporizar la misma leche."},{"q":"¿Puedo guardarlo o usar otra leche?","a":"Se propone servirlo inmediatamente, sin guardar para recalentar. La leche sin lactosa o vegetal cambia la espuma y la nutrición; el cálculo solo corresponde a leche entera pasteurizada y todo el peso medido."}]},"published":false,"editorial_status":"draft","content_html":"<p>Este capuchino combina un espresso recién preparado con leche entera pasteurizada y una capa de espuma fina. No lleva cacao, chocolate, nata ni azúcar añadida; los azúcares del cálculo proceden principalmente de la leche. Se necesita una cafetera de espresso y una lanza de vapor apta para pequeñas cantidades, una jarra y un termómetro.</p><p>La propuesta rinde una taza de unos 180–200 ml según el aire incorporado. Se estiman 5 minutos de preparación y 5 para preparar el café y calentar la leche, 10 en total una vez que la máquina está lista. El precalentamiento de cada cafetera puede añadir tiempo. Cantidades, tiempos y volumen final están pendientes de prueba de cocina; no se afirma una proporción tradicional universal de tres partes iguales.</p>"},{"id":"03eaadba-327c-58eb-a350-9cfae3aec584","recipe_group_id":"cc320b67-294e-4420-b904-4bd3d12d4c1b","language":"de","slug":"cappuccino-rezept","public_path":"/de/cappuccino-rezept","source_url":null,"title":"Cappuccino mit Espresso und Milch selbst machen","excerpt":"Cappuccino ohne zugesetzten Zucker mit 36 g Espresso, 120 g Vollmilch, feinem Schaum und Temperaturkontrolle.","summary":"Frischer Espresso wird mit pasteurisierter Vollmilch und feinem Milchschaum kombiniert. Ohne Kakao, Schokolade, Sahne oder zugesetzten Zucker; der berechnete Zucker stammt überwiegend aus Milch. Benötigt werden Espressomaschine, eine für kleine Mengen geeignete Dampflanze, Kännchen und Thermometer.\n\nVorgeschlagen ist eine Tasse mit etwa 180–200 ml je nach eingebrachter Luft. Geschätzt werden 5 Minuten Vorbereitung und 5 für Kaffee und Milch, insgesamt 10 nach Betriebsbereitschaft der Maschine. Das Aufheizen kann Zeit hinzufügen. Mengen, Zeiten und Volumen sind noch nicht in der Küche erprobt. Ein allgemeingültiges traditionelles Verhältnis dreier gleicher Teile wird nicht behauptet.","category":"Getränke","category_slug":"bebidas","difficulty":"Mittel","course":"Getränk","cuisine":"Italienisch, Vorschlag für zu Hause","prep_time_minutes":5,"cook_time_minutes":5,"total_time_minutes":10,"servings":1,"keywords":["Cappuccino selbst machen","Espresso mit Milch","Milchschaum","Cappuccino Rezept"],"ingredients":[{"name":"frisch zubereiteter Espresso","amount":"36","unit":"g fertiges Getränk, nicht Kaffeepulver","group":"Kaffee"},{"name":"kalte pasteurisierte Vollmilch","amount":"120","unit":"g","group":"Milch"}],"steps":[{"title":"Tasse, Kännchen und Milch vorbereiten","content":"Eine Tasse mit 180–200 ml, ein zur Milchmenge passendes kleines Dampfkännchen und ein sauberes Thermometer verwenden. Tasse mit heißem Wasser wärmen und vollständig leeren. 120 g kalte Milch bei höchstens 4 °C ins Kännchen wiegen; nicht bei Raumtemperatur stehen lassen. Aufheizen und Spülen nach Maschinenanleitung.","image_alt":"Milchkännchen neben leerer Tasse und Espressomaschine","image_url":"/recetas/receta-de-capuchino/paso-01.webp"},{"title":"Espresso zubereiten und wiegen","content":"Espresso in die warme Tasse beziehen und 36 g frisch extrahiertes Getränk ohne Tassengewicht abwiegen. Kann die Maschine nicht gleichzeitig brühen und dampfen, die Reihenfolge der Anleitung beachten und den Kaffee nicht lange stehen lassen. Gemeint ist fertige Flüssigkeit, nicht trockenes Kaffeepulver. Keinen Zucker oder Kakao hinzufügen.","image_alt":"Frischer Espresso läuft aus dem Siebträger in eine Tasse","image_url":"/recetas/receta-de-capuchino/paso-02.webp"},{"title":"Milch ohne Kochen texturieren","content":"Dampflanze kurz zur Abtropfschale ausblasen; Hände vom Dampf fernhalten. Spitze nahe der Oberfläche der 120 g Milch einsetzen und mit sanftem Zischen Luft einbringen, ohne große Blasen. Spitze etwas tiefer halten, sodass ein Wirbel entsteht. Bei Thermometeranzeige 55–60 °C den Dampf stoppen, bevor das Kännchen entfernt wird. Nicht kochen und nicht nur nach Zeit erhitzen; die Maschinenleistung variiert.","image_alt":"Dampflanze texturiert Milch im Edelstahlkännchen","image_url":"/recetas/receta-de-capuchino/paso-03.webp"},{"title":"Schaum verbinden und Lanze reinigen","content":"Lanze sofort mit einem sauberen, dafür bestimmten Tuch abwischen und nach Anleitung ausblasen; Verbrennungen vermeiden. Kännchen sanft auf einem Tuch aufklopfen und schwenken, damit Schaum und Milch sich verbinden. Die Milch soll glänzend und fließend sein, ohne getrennte große Blasen. Bereits erhitzte Milch nicht erneut dampfen.","image_alt":"Glänzende texturierte Milch nach sanftem Schwenken","image_url":"/recetas/receta-de-capuchino/paso-04.webp"},{"title":"Eingießen und sofort servieren","content":"Milch in einem gleichmäßigen Strahl zum 36 g Espresso gießen, zum Schluss das Kännchen annähern und feinen Schaum auflegen. Für die Schätzung die gesamte gewogene Milch verwenden; ein Muster ist nicht nötig. Sofort servieren und prüfen, dass die Tasse nicht verbrennt. Das vorgeschlagene Volumen von 180–200 ml hängt vom Schaum ab. Nicht zum Wiedererhitzen lagern: übrige texturierte Milch entsorgen, unbenutzte kalte Milch gekühlt halten.","image_alt":"Fertiger Cappuccino mit feinem Schaum in einer Keramiktasse","image_url":"/recetas/receta-de-capuchino/paso-05.webp"}],"notes":"Enthält Milch und Koffein. Ausgangspunkt für Espresso: 18 g Kaffeepulver für 36 g Getränk, Verhältnis 1:2, in etwa 25–35 Sekunden; Mahlgrad und Rezept ans Gerät anpassen. Das ersetzt die Zutat fertiger Espresso und wird nicht zusätzlich verwendet. Kaffeesatz wird nicht gegessen oder als 18 g essbarer Kaffee berechnet. Passende Siebdosis und Maschinenanleitung beachten. Benötigen Kännchen oder Lanze mehr als 120 g Milch, ist das Gerät für diese Einzeltassenformel ungeeignet; Überschuss nicht erneut erhitzen. Laktosefreie Milch kann schäumen, verändert aber Nährwerte. Pflanzendrinks verändern Schaum, Geschmack und Nährwerte und brauchen eine andere Rezeptur; diese ist nicht vegan. Zucker, Kakao und Zimt sind nicht enthalten. Kein exakter Koffeingehalt versprochen: Sorte, Dosis und Extraktion wirken sich aus. Milch kalt halten und nur pasteurisierte verwenden. Dampf und Tasse können verbrennen; Thermometer nicht an die heiße Lanze legen.","nutrition":{"fiber_g":0,"sodium_mg":57,"saturated_fat_g":2.3,"fat_g":4,"protein_g":3.8,"sugar_g":6.1,"carbs_g":6.4,"calories":76.4,"estimated":true,"serving_size":"1 vorgeschlagene Tasse mit der gesamten Milch","source":"USDA FoodData Central — SR Legacy, April 2018 JSON","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Zwei USDA-Datensätze im offiziellen Archiv über FDC-ID geprüft: 36 g fertiger Espresso und 120 g Vollmilch. Eine Portion. Ohne Kaffeesatz, Wasser zum Tassenwärmen und eingebrachte Luft. Die gesamte gewogene Milch wird in der Tasse angenommen.","note":"Schätzung, keine Getränkeanalyse. Milch, Extraktion und Reste im Kännchen verändern das Ergebnis. Volumen, Zeiten und Ausbeute sind noch nicht in der Küche erprobt. Ohne zugesetzten Zucker oder Koffeinberechnung.","inputs":[{"fdc_id":171891,"fdc_description":"Beverages, coffee, brewed, espresso, restaurant-prepared","per_100g":{"fiber_g":0,"sodium_mg":14,"saturated_fat_g":0.092,"fat_g":0.18,"protein_g":0.12,"sugar_g":0,"carbs_g":1.67,"calories":9},"source_url":"https://fdc.nal.usda.gov/food-details/171891/nutrients","ingredient":"frisch zubereiteter Espresso","edible_grams":36},{"fdc_id":171265,"fdc_description":"Milk, whole, 3.25% milkfat, with added vitamin D","per_100g":{"fat_g":3.25,"sugar_g":5.05,"carbs_g":4.8,"calories":61,"saturated_fat_g":1.86,"fiber_g":0,"sodium_mg":43,"protein_g":3.15},"source_url":"https://fdc.nal.usda.gov/food-details/171265/nutrients","ingredient":"kalte pasteurisierte Vollmilch","edible_grams":120}]},"image_url":"/recetas/receta-de-capuchino/portada.webp","gallery":[{"url":"/recetas/receta-de-capuchino/portada.webp","alt":"Selbst gemachter Cappuccino mit feinem Milchschaum und Espressocrema"}],"seo":{"title":"Cappuccino selbst machen mit Espresso | Manual de Cocina","description":"Cappuccino ohne zugesetzten Zucker aus abgewogenem Espresso und Milch. Bei 55–60 °C texturieren und mit feinem Schaum servieren.","image_alt":"Selbst gemachter Cappuccino mit feinem Milchschaum und Espressocrema","image_variants":["/recetas/receta-de-capuchino/portada-1x1.webp","/recetas/receta-de-capuchino/portada-4x3.webp","/recetas/receta-de-capuchino/portada-16x9.webp"],"faq":[{"q":"Warum 36 g Espresso statt 36 g Kaffeepulver?","a":"Es ist das Gewicht des fertigen Getränks. Als Ausgangspunkt ergeben 18 g trockener Kaffee 36 g Espresso, Verhältnis 1:2. Kaffeesatz entsorgen; er kommt weder in die Tasse noch in die Nährwertberechnung."},{"q":"Warum entstehen große Schaumblasen?","a":"Oft wird zu viel Luft eingebracht oder die Spitze liegt zu hoch. Anfangs sanft Luft einbringen, dann einen Wirbel bilden und das Kännchen schwenken. Bei 55–60 °C stoppen und dieselbe Milch nicht erneut dampfen."},{"q":"Kann ich den Cappuccino lagern oder andere Milch verwenden?","a":"Sofort servieren, nicht zum Wiedererhitzen lagern. Laktosefreie Milch und Pflanzendrinks verändern Schaum und Nährwerte. Die Berechnung gilt nur für pasteurisierte Vollmilch und das gesamte abgewogene Gewicht."}]},"published":false,"editorial_status":"draft","content_html":"<p>Frischer Espresso wird mit pasteurisierter Vollmilch und feinem Milchschaum kombiniert. Ohne Kakao, Schokolade, Sahne oder zugesetzten Zucker; der berechnete Zucker stammt überwiegend aus Milch. Benötigt werden Espressomaschine, eine für kleine Mengen geeignete Dampflanze, Kännchen und Thermometer.</p><p>Vorgeschlagen ist eine Tasse mit etwa 180–200 ml je nach eingebrachter Luft. Geschätzt werden 5 Minuten Vorbereitung und 5 für Kaffee und Milch, insgesamt 10 nach Betriebsbereitschaft der Maschine. Das Aufheizen kann Zeit hinzufügen. Mengen, Zeiten und Volumen sind noch nicht in der Küche erprobt. Ein allgemeingültiges traditionelles Verhältnis dreier gleicher Teile wird nicht behauptet.</p>"},{"id":"78ffb3c0-b2eb-53b0-acb6-4378773615f0","recipe_group_id":"cc320b67-294e-4420-b904-4bd3d12d4c1b","language":"en","slug":"cappuccino-recipe","public_path":"/en/cappuccino-recipe","source_url":null,"title":"Homemade cappuccino with espresso and milk","excerpt":"A cappuccino without added sugar, using 36 g espresso and 120 g whole milk, fine foam and a temperature check.","summary":"Fresh espresso is combined with pasteurised whole milk and fine foam. No cocoa, chocolate, cream or added sugar is included; the calculated sugars come mainly from milk. You need an espresso machine with a steam wand suitable for small quantities, a pitcher and a thermometer.\n\nThe proposed yield is one cup of about 180–200 ml depending on incorporated air. Allow an estimated 5 minutes preparation and 5 for coffee and milk, 10 overall once the machine is ready. Machine warm-up may add time. Quantities, timings and volume await a kitchen trial. This is not claimed to follow a universal traditional ratio of three equal parts.","category":"Drinks","category_slug":"bebidas","difficulty":"Medium","course":"Drink","cuisine":"Italian, home-style proposal","prep_time_minutes":5,"cook_time_minutes":5,"total_time_minutes":10,"servings":1,"keywords":["homemade cappuccino","espresso with milk","milk foam","cappuccino recipe"],"ingredients":[{"name":"freshly prepared espresso","amount":"36","unit":"g of beverage, not ground coffee","group":"Coffee"},{"name":"cold pasteurised whole milk","amount":"120","unit":"g","group":"Milk"}],"steps":[{"title":"Prepare the cup, pitcher and milk","content":"Use a 180–200 ml cup, a small steaming pitcher compatible with the milk quantity and a clean thermometer. Warm the cup with hot water and empty completely. Weigh 120 g cold milk at 4 °C or below into the pitcher; do not leave it at room temperature. Follow your machine manual for warm-up and purging.","image_alt":"Pitcher of cold milk beside an empty cup and espresso machine","image_url":"/recetas/receta-de-capuchino/paso-01.webp"},{"title":"Prepare and weigh the espresso","content":"Brew espresso into the warm cup and weigh 36 g freshly extracted beverage, excluding the cup weight. If your machine cannot brew and steam simultaneously, follow its manual sequence and avoid leaving coffee for long. This is prepared liquid weight, not dry coffee. Add no sugar or cocoa in this version.","image_alt":"Fresh espresso being extracted into a cup under the portafilter","image_url":"/recetas/receta-de-capuchino/paso-02.webp"},{"title":"Texture the milk without boiling","content":"Briefly purge the wand toward the drip tray, keeping hands away from steam. Put the tip near the surface of the 120 g milk and open the steam to introduce air with a gentle hiss, rather than large bubbles. Lower the tip slightly to create a whirlpool. Stop steam when the thermometer reads 55–60 °C, before removing the pitcher. Do not boil or rely on a fixed time: machine power varies.","image_alt":"Steam wand texturing milk in a stainless pitcher","image_url":"/recetas/receta-de-capuchino/paso-03.webp"},{"title":"Combine foam and clean the wand","content":"Immediately wipe the wand with a clean dedicated cloth and purge as directed by the manual, avoiding burns. Tap the pitcher base gently on a cloth and swirl to combine foam and liquid. It should look glossy and fluid, without separate large bubbles. Do not steam already heated milk again.","image_alt":"Glossy textured milk after gently swirling the pitcher","image_url":"/recetas/receta-de-capuchino/paso-04.webp"},{"title":"Pour and serve immediately","content":"Pour milk into the 36 g espresso in a continuous stream, bringing the pitcher closer at the end to deposit fine foam. Use all weighed milk for the estimate to apply; no pattern is required. Serve immediately and make sure the cup will not burn. The proposed 180–200 ml volume depends on foam. Do not store this drink for reheating: discard leftover textured milk and keep unused cold milk refrigerated.","image_alt":"Finished cappuccino with fine foam in a ceramic cup","image_url":"/recetas/receta-de-capuchino/paso-05.webp"}],"notes":"Contains milk and caffeine. For espresso, a starting point is 18 g grounds yielding 36 g beverage, a 1:2 ratio, in about 25–35 seconds; adjust grind and recipe to your equipment. This preparation replaces the ready espresso ingredient, rather than being added to it. Grounds are discarded, not eaten or counted as 18 g edible coffee. Use the dose suited to the basket and follow the machine manual. If the pitcher or wand needs more than 120 g milk, the equipment is unsuitable for this single-cup formula; never reheat the excess. Lactose-free milk can foam but changes nutrition. Plant drinks alter foam, flavour and nutrients and need another formulation; this one is not vegan. Optional sugar, cocoa and cinnamon are excluded. No exact caffeine content is promised: variety, dose and extraction vary. Keep milk cold and use pasteurised milk only. Steam and the cup can burn; do not let the thermometer touch the hot wand.","nutrition":{"fiber_g":0,"sodium_mg":57,"saturated_fat_g":2.3,"fat_g":4,"protein_g":3.8,"sugar_g":6.1,"carbs_g":6.4,"calories":76.4,"estimated":true,"serving_size":"1 proposed cup with all measured milk","source":"USDA FoodData Central — SR Legacy, April 2018 JSON","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Two USDA records verified by FDC ID in the official archive: 36 g prepared espresso and 120 g whole milk. One serving. Coffee grounds, cup-warming water and incorporated air are excluded. All weighed milk is assumed to reach the cup.","note":"Estimate, not beverage analysis. Actual milk, extraction and liquid left in the pitcher change the result. Volume, timings and yield await a kitchen trial. No added sugar or caffeine calculation.","inputs":[{"fdc_id":171891,"fdc_description":"Beverages, coffee, brewed, espresso, restaurant-prepared","per_100g":{"fiber_g":0,"sodium_mg":14,"saturated_fat_g":0.092,"fat_g":0.18,"protein_g":0.12,"sugar_g":0,"carbs_g":1.67,"calories":9},"source_url":"https://fdc.nal.usda.gov/food-details/171891/nutrients","ingredient":"freshly prepared espresso","edible_grams":36},{"fdc_id":171265,"fdc_description":"Milk, whole, 3.25% milkfat, with added vitamin D","per_100g":{"fat_g":3.25,"sugar_g":5.05,"carbs_g":4.8,"calories":61,"saturated_fat_g":1.86,"fiber_g":0,"sodium_mg":43,"protein_g":3.15},"source_url":"https://fdc.nal.usda.gov/food-details/171265/nutrients","ingredient":"cold pasteurised whole milk","edible_grams":120}]},"image_url":"/recetas/receta-de-capuchino/portada.webp","gallery":[{"url":"/recetas/receta-de-capuchino/portada.webp","alt":"Homemade cappuccino with fine milk foam and espresso crema"}],"seo":{"title":"Homemade espresso cappuccino: step by step | Manual de Cocina","description":"Cappuccino without added sugar using measured espresso and milk. Texture at 55–60 °C and serve with fine foam; a proposed single-cup recipe.","image_alt":"Homemade cappuccino with fine milk foam and espresso crema","image_variants":["/recetas/receta-de-capuchino/portada-1x1.webp","/recetas/receta-de-capuchino/portada-4x3.webp","/recetas/receta-de-capuchino/portada-16x9.webp"],"faq":[{"q":"Why 36 g espresso rather than 36 g ground coffee?","a":"It is the weight of prepared beverage. A starting point is 18 g dry coffee yielding 36 g espresso, a 1:2 ratio. Discard the grounds; they are not added to the cup or nutrition calculation."},{"q":"Why does the foam have large bubbles?","a":"Too much air or a tip placed too high is often responsible. Introduce air gently at first, then create a whirlpool and swirl the pitcher afterwards. Stop at 55–60 °C and do not steam the same milk again."},{"q":"Can I store it or use another milk?","a":"Serve immediately without storing for reheating. Lactose-free or plant milk changes foam and nutrition; this calculation covers pasteurised whole milk and its full measured weight only."}]},"published":false,"editorial_status":"draft","content_html":"<p>Fresh espresso is combined with pasteurised whole milk and fine foam. No cocoa, chocolate, cream or added sugar is included; the calculated sugars come mainly from milk. You need an espresso machine with a steam wand suitable for small quantities, a pitcher and a thermometer.</p><p>The proposed yield is one cup of about 180–200 ml depending on incorporated air. Allow an estimated 5 minutes preparation and 5 for coffee and milk, 10 overall once the machine is ready. Machine warm-up may add time. Quantities, timings and volume await a kitchen trial. This is not claimed to follow a universal traditional ratio of three equal parts.</p>"},{"id":"96f5b007-9415-54c7-9b10-4f1c8d711607","recipe_group_id":"cc320b67-294e-4420-b904-4bd3d12d4c1b","language":"fr","slug":"recette-de-cappuccino","public_path":"/fr/recette-de-cappuccino","source_url":null,"title":"Cappuccino maison avec espresso et lait","excerpt":"Un cappuccino sans sucre ajouté avec 36 g d’espresso, 120 g de lait entier, mousse fine et contrôle de température.","summary":"Un espresso frais est associé à du lait entier pasteurisé et une mousse fine. Sans cacao, chocolat, crème ni sucre ajouté ; les sucres calculés proviennent surtout du lait. Il faut une machine à espresso, une buse adaptée aux petites quantités, un pichet et un thermomètre.\n\nLa proposition donne une tasse d’environ 180–200 ml selon l’air incorporé. Comptez 5 minutes de préparation et 5 pour le café et le lait, soit 10 une fois la machine prête. Son préchauffage peut ajouter du temps. Quantités, durées et volume attendent un essai en cuisine. Aucun ratio traditionnel universel de trois parts égales n’est affirmé.","category":"Boissons","category_slug":"bebidas","difficulty":"Moyenne","course":"Boisson","cuisine":"Italienne, proposition maison","prep_time_minutes":5,"cook_time_minutes":5,"total_time_minutes":10,"servings":1,"keywords":["cappuccino maison","espresso au lait","mousse de lait","recette cappuccino"],"ingredients":[{"name":"espresso fraîchement préparé","amount":"36","unit":"g de boisson, pas de café moulu","group":"Café"},{"name":"lait entier pasteurisé froid","amount":"120","unit":"g","group":"Lait"}],"steps":[{"title":"Préparer tasse, pichet et lait","content":"Utilisez une tasse de 180–200 ml, un petit pichet compatible avec la quantité de lait et un thermomètre propre. Chauffez la tasse à l’eau chaude et videz-la complètement. Pesez 120 g de lait froid à 4 °C ou moins dans le pichet ; ne le laissez pas à température ambiante. Suivez le manuel pour préchauffage et purge.","image_alt":"Pichet de lait froid près d’une tasse vide et d’une machine espresso","image_url":"/recetas/receta-de-capuchino/paso-01.webp"},{"title":"Préparer et peser l’espresso","content":"Extrayez le café dans la tasse chaude et pesez 36 g de boisson fraîche, sans le poids de la tasse. Si la machine ne permet pas extraction et vapeur simultanées, suivez son ordre de fonctionnement et ne laissez pas attendre le café longtemps. Il s’agit de liquide préparé, pas de café sec. N’ajoutez ni sucre ni cacao.","image_alt":"Espresso fraîchement extrait sous le porte-filtre","image_url":"/recetas/receta-de-capuchino/paso-02.webp"},{"title":"Texturer le lait sans le faire bouillir","content":"Purgez brièvement la buse vers le bac, mains loin de la vapeur. Placez la pointe près de la surface des 120 g de lait et ouvrez la vapeur pour incorporer l’air avec un léger sifflement, sans grosses bulles. Enfoncez légèrement pour créer un tourbillon. Arrêtez à 55–60 °C au thermomètre, avant de retirer le pichet. Ne faites pas bouillir et ne chauffez pas selon une durée fixe ; la puissance varie.","image_alt":"Buse vapeur texturant le lait dans un pichet métallique","image_url":"/recetas/receta-de-capuchino/paso-03.webp"},{"title":"Unir la mousse et nettoyer la buse","content":"Essuyez aussitôt la buse avec un linge propre réservé à cet usage et purgez selon le manuel sans vous brûler. Tapotez doucement le fond du pichet sur un linge, puis faites tourner le lait pour unir liquide et mousse. Il doit être brillant et fluide, sans grosses bulles séparées. Ne repassez pas à la vapeur un lait déjà chauffé.","image_alt":"Lait texturé brillant après rotation douce du pichet","image_url":"/recetas/receta-de-capuchino/paso-04.webp"},{"title":"Verser et servir immédiatement","content":"Versez le lait sur les 36 g d’espresso en filet continu, puis approchez le pichet pour déposer la mousse fine. Utilisez tout le lait pesé pour respecter le calcul ; aucun dessin n’est nécessaire. Servez aussitôt et vérifiez que la tasse ne brûle pas. Le volume proposé de 180–200 ml dépend de la mousse. Ne gardez pas cette boisson pour la réchauffer : jetez le lait texturé restant et gardez le lait froid inutilisé au réfrigérateur.","image_alt":"Cappuccino fini avec mousse fine dans une tasse","image_url":"/recetas/receta-de-capuchino/paso-05.webp"}],"notes":"Contient lait et caféine. Point de départ possible : 18 g de café moulu pour 36 g de boisson, ratio 1:2, en environ 25–35 secondes ; adaptez mouture et recette à la machine. Cela remplace l’ingrédient espresso préparé, sans s’y ajouter. Le marc n’est pas consommé ni compté comme 18 g de café comestible. Respectez dose du panier et manuel. Si pichet ou buse exige plus de 120 g de lait, l’équipement ne convient pas à cette tasse ; ne réchauffez pas le surplus. Le lait sans lactose peut mousser mais change la nutrition. Une boisson végétale change mousse, goût et nutriments et demande une autre fiche ; celle-ci n’est pas végétalienne. Sucre, cacao et cannelle ne sont pas inclus. Aucun taux précis de caféine n’est promis : variété, dose et extraction le modifient. Gardez le lait froid et utilisez uniquement du lait pasteurisé. Vapeur et tasse peuvent brûler ; ne laissez pas le thermomètre toucher la buse chaude.","nutrition":{"fiber_g":0,"sodium_mg":57,"saturated_fat_g":2.3,"fat_g":4,"protein_g":3.8,"sugar_g":6.1,"carbs_g":6.4,"calories":76.4,"estimated":true,"serving_size":"1 tasse proposée avec tout le lait pesé","source":"USDA FoodData Central — SR Legacy, April 2018 JSON","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Deux fiches USDA vérifiées par FDC ID dans l’archive officielle : 36 g d’espresso préparé et 120 g de lait entier. Une portion. Marc, eau de préchauffage de la tasse et air exclus. Tout le lait pesé est supposé versé.","note":"Estimation, pas analyse de la boisson. Lait, extraction et liquide restant au pichet changent le résultat. Volume, durées et rendement attendent un essai en cuisine. Sans sucre ajouté ni calcul de caféine.","inputs":[{"fdc_id":171891,"fdc_description":"Beverages, coffee, brewed, espresso, restaurant-prepared","per_100g":{"fiber_g":0,"sodium_mg":14,"saturated_fat_g":0.092,"fat_g":0.18,"protein_g":0.12,"sugar_g":0,"carbs_g":1.67,"calories":9},"source_url":"https://fdc.nal.usda.gov/food-details/171891/nutrients","ingredient":"espresso fraîchement préparé","edible_grams":36},{"fdc_id":171265,"fdc_description":"Milk, whole, 3.25% milkfat, with added vitamin D","per_100g":{"fat_g":3.25,"sugar_g":5.05,"carbs_g":4.8,"calories":61,"saturated_fat_g":1.86,"fiber_g":0,"sodium_mg":43,"protein_g":3.15},"source_url":"https://fdc.nal.usda.gov/food-details/171265/nutrients","ingredient":"lait entier pasteurisé froid","edible_grams":120}]},"image_url":"/recetas/receta-de-capuchino/portada.webp","gallery":[{"url":"/recetas/receta-de-capuchino/portada.webp","alt":"Cappuccino maison à la mousse fine et à la crema d’espresso"}],"seo":{"title":"Cappuccino maison avec espresso, pas à pas | Manual de Cocina","description":"Cappuccino sans sucre ajouté avec espresso et lait pesés. Texturez à 55–60 °C et servez avec une mousse fine ; proposition pour une tasse.","image_alt":"Cappuccino maison à la mousse fine et à la crema d’espresso","image_variants":["/recetas/receta-de-capuchino/portada-1x1.webp","/recetas/receta-de-capuchino/portada-4x3.webp","/recetas/receta-de-capuchino/portada-16x9.webp"],"faq":[{"q":"Pourquoi 36 g d’espresso et non de café moulu ?","a":"C’est le poids de la boisson préparée. On peut partir de 18 g de café sec pour obtenir 36 g d’espresso, ratio 1:2. Jetez le marc ; il ne va ni dans la tasse ni dans le calcul nutritionnel."},{"q":"Pourquoi la mousse a-t-elle de grosses bulles ?","a":"Trop d’air ou une pointe trop haute en sont souvent la cause. Incorporez doucement l’air au début, puis formez un tourbillon et faites tourner le pichet. Arrêtez à 55–60 °C et ne vaporisez pas de nouveau le même lait."},{"q":"Peut-on conserver la boisson ou changer de lait ?","a":"Servez immédiatement sans conserver pour réchauffer. Lait sans lactose et boissons végétales changent mousse et nutrition ; le calcul concerne seulement le lait entier pasteurisé et tout son poids mesuré."}]},"published":false,"editorial_status":"draft","content_html":"<p>Un espresso frais est associé à du lait entier pasteurisé et une mousse fine. Sans cacao, chocolat, crème ni sucre ajouté ; les sucres calculés proviennent surtout du lait. Il faut une machine à espresso, une buse adaptée aux petites quantités, un pichet et un thermomètre.</p><p>La proposition donne une tasse d’environ 180–200 ml selon l’air incorporé. Comptez 5 minutes de préparation et 5 pour le café et le lait, soit 10 une fois la machine prête. Son préchauffage peut ajouter du temps. Quantités, durées et volume attendent un essai en cuisine. Aucun ratio traditionnel universel de trois parts égales n’est affirmé.</p>"},{"id":"3021dce8-571d-5969-91f7-84d3733a5482","recipe_group_id":"cc320b67-294e-4420-b904-4bd3d12d4c1b","language":"it","slug":"ricetta-cappuccino","public_path":"/it/ricetta-cappuccino","source_url":null,"title":"Cappuccino fatto in casa con espresso e latte","excerpt":"Cappuccino senza zucchero aggiunto con 36 g di espresso, 120 g di latte intero, schiuma fine e temperatura controllata.","summary":"Espresso appena fatto, latte intero pastorizzato e schiuma fine. Senza cacao, cioccolato, panna o zucchero aggiunto; gli zuccheri calcolati provengono soprattutto dal latte. Servono macchina espresso, lancia adatta a piccole quantità, bricco e termometro.\n\nLa proposta rende una tazza di circa 180–200 ml secondo l’aria incorporata. Si stimano 5 minuti di preparazione e 5 per caffè e latte, 10 totali quando la macchina è pronta. Il riscaldamento della macchina può aggiungere tempo. Dosi, tempi e volume attendono prova in cucina; non si afferma un rapporto tradizionale universale di tre parti uguali.","category":"Bevande","category_slug":"bebidas","difficulty":"Media","course":"Bevanda","cuisine":"Italiana, proposta casalinga","prep_time_minutes":5,"cook_time_minutes":5,"total_time_minutes":10,"servings":1,"keywords":["cappuccino fatto in casa","espresso e latte","schiuma di latte","ricetta cappuccino"],"ingredients":[{"name":"espresso appena preparato","amount":"36","unit":"g di bevanda, non di caffè macinato","group":"Caffè"},{"name":"latte intero pastorizzato freddo","amount":"120","unit":"g","group":"Latte"}],"steps":[{"title":"Preparare tazza, bricco e latte","content":"Usare una tazza da 180–200 ml, un piccolo bricco adatto alla quantità di latte e un termometro pulito. Scaldare la tazza con acqua calda e svuotarla completamente. Pesare 120 g di latte freddo a 4 °C o meno nel bricco; non lasciarlo a temperatura ambiente. Seguire il manuale per riscaldamento e spurgo.","image_alt":"Bricco con latte freddo accanto a tazza vuota e macchina espresso","image_url":"/recetas/receta-de-capuchino/paso-01.webp"},{"title":"Preparare e pesare l’espresso","content":"Estrarre espresso nella tazza calda e pesare 36 g di bevanda fresca, escludendo il peso della tazza. Se non si possono usare estrazione e vapore insieme, seguire la sequenza del manuale senza far attendere a lungo il caffè. È peso di liquido preparato, non caffè secco. Non aggiungere zucchero o cacao.","image_alt":"Espresso appena estratto sotto il portafiltro","image_url":"/recetas/receta-de-capuchino/paso-02.webp"},{"title":"Montare il latte senza bollirlo","content":"Spurgare brevemente la lancia verso la vaschetta, tenendo le mani lontane dal vapore. Mettere la punta vicino alla superficie dei 120 g di latte e aprire il vapore per introdurre aria con un sibilo delicato, senza grandi bolle. Immergere un poco per creare un vortice. Fermare il vapore quando il termometro indica 55–60 °C, prima di togliere il bricco. Non bollire o basarsi su un tempo fisso: la potenza cambia.","image_alt":"Lancia che monta il latte in un bricco metallico","image_url":"/recetas/receta-de-capuchino/paso-03.webp"},{"title":"Unire la schiuma e pulire la lancia","content":"Pulire subito la lancia con un panno pulito dedicato e spurgare secondo il manuale, evitando scottature. Battere delicatamente la base del bricco su un panno e ruotare il latte per unire schiuma e liquido. Deve essere lucido e fluido, senza grandi bolle separate. Non vaporizzare di nuovo latte già scaldato.","image_alt":"Latte montato lucido dopo aver ruotato il bricco","image_url":"/recetas/receta-de-capuchino/paso-04.webp"},{"title":"Versare e servire subito","content":"Versare il latte sui 36 g di espresso a filo continuo, avvicinando il bricco alla fine per depositare la schiuma fine. Usare tutto il latte pesato per rispettare la stima; non serve disegnare. Servire subito e verificare che la tazza non scotti. Il volume proposto di 180–200 ml dipende dalla schiuma. Non conservare per riscaldare: eliminare il latte montato avanzato e tenere al freddo quello inutilizzato.","image_alt":"Cappuccino pronto con schiuma fine in tazza","image_url":"/recetas/receta-de-capuchino/paso-05.webp"}],"notes":"Contiene latte e caffeina. Per l’espresso si può partire da 18 g di caffè macinato per 36 g di bevanda, rapporto 1:2, in circa 25–35 secondi; adattare macinatura e ricetta. Questo sostituisce l’ingrediente espresso pronto, non si aggiunge. I fondi non si mangiano e non si contano come 18 g di caffè edibile. Usare dose adatta al filtro e seguire il manuale. Se bricco o lancia richiedono più di 120 g di latte, l’attrezzatura non è adatta a questa tazza; non riscaldare gli avanzi. Il latte senza lattosio può montare ma cambia la nutrizione. Bevande vegetali cambiano schiuma, sapore e nutrienti e richiedono altra formulazione; questa non è vegana. Non sono inclusi zucchero, cacao o cannella. Non si promette una quantità precisa di caffeina: varietà, dose ed estrazione la modificano. Tenere il latte freddo e usare solo pastorizzato. Vapore e tazza possono scottare; il termometro non deve toccare la lancia calda.","nutrition":{"fiber_g":0,"sodium_mg":57,"saturated_fat_g":2.3,"fat_g":4,"protein_g":3.8,"sugar_g":6.1,"carbs_g":6.4,"calories":76.4,"estimated":true,"serving_size":"1 tazza proposta con tutto il latte pesato","source":"USDA FoodData Central — SR Legacy, April 2018 JSON","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Due schede USDA verificate tramite FDC ID nell’archivio ufficiale: 36 g di espresso preparato e 120 g di latte intero. Una porzione. Esclusi fondi, acqua per scaldare la tazza e aria. Si presume che tutto il latte pesato finisca nella tazza.","note":"Stima, non analisi della bevanda. Latte, estrazione e liquido rimasto nel bricco cambiano il risultato. Volume, tempi e resa attendono prova in cucina. Senza zucchero aggiunto o calcolo della caffeina.","inputs":[{"fdc_id":171891,"fdc_description":"Beverages, coffee, brewed, espresso, restaurant-prepared","per_100g":{"fiber_g":0,"sodium_mg":14,"saturated_fat_g":0.092,"fat_g":0.18,"protein_g":0.12,"sugar_g":0,"carbs_g":1.67,"calories":9},"source_url":"https://fdc.nal.usda.gov/food-details/171891/nutrients","ingredient":"espresso appena preparato","edible_grams":36},{"fdc_id":171265,"fdc_description":"Milk, whole, 3.25% milkfat, with added vitamin D","per_100g":{"fat_g":3.25,"sugar_g":5.05,"carbs_g":4.8,"calories":61,"saturated_fat_g":1.86,"fiber_g":0,"sodium_mg":43,"protein_g":3.15},"source_url":"https://fdc.nal.usda.gov/food-details/171265/nutrients","ingredient":"latte intero pastorizzato freddo","edible_grams":120}]},"image_url":"/recetas/receta-de-capuchino/portada.webp","gallery":[{"url":"/recetas/receta-de-capuchino/portada.webp","alt":"Cappuccino casalingo con schiuma fine e crema dell’espresso"}],"seo":{"title":"Cappuccino casalingo con espresso: i passaggi | Manual de Cocina","description":"Cappuccino senza zucchero aggiunto con espresso e latte pesati. Monta a 55–60 °C e servi con schiuma fine; proposta per una tazza.","image_alt":"Cappuccino casalingo con schiuma fine e crema dell’espresso","image_variants":["/recetas/receta-de-capuchino/portada-1x1.webp","/recetas/receta-de-capuchino/portada-4x3.webp","/recetas/receta-de-capuchino/portada-16x9.webp"],"faq":[{"q":"Perché 36 g di espresso e non di caffè macinato?","a":"È il peso della bevanda pronta. Un punto di partenza è 18 g di caffè secco per ottenere 36 g di espresso, rapporto 1:2. Eliminare i fondi; non si aggiungono alla tazza né al calcolo nutrizionale."},{"q":"Perché la schiuma ha bolle grandi?","a":"Spesso entra troppa aria o la punta è troppo alta. Introdurre aria dolcemente all’inizio, poi creare un vortice e ruotare il bricco. Fermarsi a 55–60 °C e non vaporizzare lo stesso latte di nuovo."},{"q":"Posso conservarlo o cambiare latte?","a":"Servire subito senza conservare per riscaldare. Latte senza lattosio e bevande vegetali cambiano schiuma e nutrienti; il calcolo riguarda solo latte intero pastorizzato e tutto il peso misurato."}]},"published":false,"editorial_status":"draft","content_html":"<p>Espresso appena fatto, latte intero pastorizzato e schiuma fine. Senza cacao, cioccolato, panna o zucchero aggiunto; gli zuccheri calcolati provengono soprattutto dal latte. Servono macchina espresso, lancia adatta a piccole quantità, bricco e termometro.</p><p>La proposta rende una tazza di circa 180–200 ml secondo l’aria incorporata. Si stimano 5 minuti di preparazione e 5 per caffè e latte, 10 totali quando la macchina è pronta. Il riscaldamento della macchina può aggiungere tempo. Dosi, tempi e volume attendono prova in cucina; non si afferma un rapporto tradizionale universale di tre parti uguali.</p>"},{"id":"73ed4995-9d93-5e75-99f0-b0d50a6126e0","recipe_group_id":"cc320b67-294e-4420-b904-4bd3d12d4c1b","language":"ja","slug":"カプチーノのレシピ","public_path":"/ja/カプチーノのレシピ","source_url":null,"title":"エスプレッソと牛乳で作る自家製カプチーノ","excerpt":"エスプレッソ36 gと全乳120 gを使う砂糖無添加のカプチーノ。細かな泡と温度を確認します。","summary":"淹れたてのエスプレッソに、殺菌済み全乳と細かな泡を合わせます。ココア、チョコレート、生クリーム、添加糖は使わず、栄養計算の糖類は主に牛乳由来です。少量に対応するスチームノズル付きエスプレッソマシン、ピッチャー、温度計が必要です。\n\n出来上がりは空気の量により約180–200 mlの1杯を提案します。準備5分、コーヒーと牛乳の加熱5分、マシンが使える状態になってから合計10分の推定です。マシンの予熱時間は別途必要になる場合があります。分量、時間、容量は調理試験待ちです。伝統的に必ず3等分する普遍的な比率とは主張しません。","category":"飲み物","category_slug":"bebidas","difficulty":"中級","course":"飲み物","cuisine":"イタリア風の家庭用レシピ案","prep_time_minutes":5,"cook_time_minutes":5,"total_time_minutes":10,"servings":1,"keywords":["カプチーノ 作り方","自家製カプチーノ","エスプレッソ 牛乳","ミルクフォーム"],"ingredients":[{"name":"淹れたてのエスプレッソ","amount":"36","unit":"g、粉ではなく抽出済みの飲料","group":"コーヒー"},{"name":"冷たい殺菌済み全乳","amount":"120","unit":"g","group":"牛乳"}],"steps":[{"title":"カップ、ピッチャー、牛乳を用意する","content":"180–200 mlのカップ、牛乳の量に適した小さなピッチャー、清潔な温度計を用意します。カップを湯で温め、完全に空にします。4 °C以下の冷たい牛乳120 gをピッチャーに量り、室温で放置しません。マシンの予熱とパージは説明書に従います。","image_alt":"空のカップとマシンの横に置いた冷たい牛乳のピッチャー","image_url":"/recetas/receta-de-capuchino/paso-01.webp"},{"title":"エスプレッソを淹れて量る","content":"温めたカップにエスプレッソを抽出し、カップの重さを除いて飲料36 gを量ります。抽出とスチームを同時に使えない機種は説明書の順序に従い、コーヒーを長く待たせません。指定重量は抽出済みの液体で、乾いたコーヒー粉ではありません。この版では砂糖やココアを加えません。","image_alt":"ポルタフィルターからカップへ抽出するエスプレッソ","image_url":"/recetas/receta-de-capuchino/paso-02.webp"},{"title":"沸騰させずに牛乳を泡立てる","content":"ノズルを受け皿へ向けて短くパージし、手を蒸気から離します。牛乳120 gの表面近くに先端を置き、蒸気を開いて柔らかな音で空気を入れ、大きな泡を作らないようにします。少し沈めて渦を作り、温度計が55–60 °Cを示したら蒸気を止めてからピッチャーを外します。沸騰させず、一定時間だけで判断しません。機種の出力が異なります。","image_alt":"金属ピッチャーの牛乳をスチームで泡立てる","image_url":"/recetas/receta-de-capuchino/paso-03.webp"},{"title":"泡をなじませ、ノズルを清掃する","content":"専用の清潔な布でノズルをすぐ拭き、やけどを避けて説明書通りにパージします。ピッチャーの底を布の上で軽くたたき、回して牛乳と泡を一体化させます。大きな泡が分離せず、つやがあり流れる状態にします。一度温めた牛乳を再度スチームにかけません。","image_alt":"ピッチャーを回してなじませたつやのある牛乳","image_url":"/recetas/receta-de-capuchino/paso-04.webp"},{"title":"注いですぐ提供する","content":"エスプレッソ36 gへ牛乳を一定の流れで注ぎ、最後にピッチャーを近づけて細かい泡をのせます。推定栄養値に合わせ、量った牛乳をすべて使います。模様は不要です。すぐ提供し、カップでやけどしないか確認します。提案する180–200 mlの容量は泡の量で変わります。保存して再加熱せず、残った泡立てた牛乳は捨て、未使用の冷たい牛乳は冷蔵します。","image_alt":"陶器のカップに入った細かい泡のカプチーノ","image_url":"/recetas/receta-de-capuchino/paso-05.webp"}],"notes":"牛乳とカフェインを含みます。エスプレッソはコーヒー粉18 gから飲料36 gを得る1:2の比率、約25–35秒を出発点にし、挽き目と配合を機器に合わせられます。これは抽出済みエスプレッソの材料を置き換える方法で、追加する材料ではありません。粉のかすは食べず、可食コーヒー18 gとして計算しません。バスケットに合う量と説明書に従ってください。ピッチャーやノズルが牛乳120 gを超える量を必要とするなら、この1杯の配合には不適切です。余りを再加熱しません。乳糖不使用の牛乳は泡立つ場合がありますが栄養値が変わります。植物性飲料は泡、味、栄養が変わり別配合が必要で、この案はヴィーガンではありません。任意の砂糖、ココア、シナモンは含めません。カフェイン量は豆、量、抽出で変わるため正確な量を保証しません。牛乳を冷蔵し、殺菌済みだけを使います。蒸気とカップでやけどに注意し、温度計を熱いノズルに当てません。","nutrition":{"fiber_g":0,"sodium_mg":57,"saturated_fat_g":2.3,"fat_g":4,"protein_g":3.8,"sugar_g":6.1,"carbs_g":6.4,"calories":76.4,"estimated":true,"serving_size":"計量した牛乳全量を使う提案の1杯","source":"USDA FoodData Central — SR Legacy, April 2018 JSON","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"公式アーカイブでFDC IDからUSDA2項目を確認。抽出済みエスプレッソ36 gと全乳120 gで1人分。コーヒーかす、カップを温める湯、空気は除外。量った牛乳全量をカップへ注ぐと仮定。","note":"飲料の分析ではなく推定。実際の牛乳、抽出、ピッチャーに残る液体により変わる。容量、時間、出来上がり量は調理試験待ち。添加糖とカフェイン計算は含まない。","inputs":[{"fdc_id":171891,"fdc_description":"Beverages, coffee, brewed, espresso, restaurant-prepared","per_100g":{"fiber_g":0,"sodium_mg":14,"saturated_fat_g":0.092,"fat_g":0.18,"protein_g":0.12,"sugar_g":0,"carbs_g":1.67,"calories":9},"source_url":"https://fdc.nal.usda.gov/food-details/171891/nutrients","ingredient":"淹れたてのエスプレッソ","edible_grams":36},{"fdc_id":171265,"fdc_description":"Milk, whole, 3.25% milkfat, with added vitamin D","per_100g":{"fat_g":3.25,"sugar_g":5.05,"carbs_g":4.8,"calories":61,"saturated_fat_g":1.86,"fiber_g":0,"sodium_mg":43,"protein_g":3.15},"source_url":"https://fdc.nal.usda.gov/food-details/171265/nutrients","ingredient":"冷たい殺菌済み全乳","edible_grams":120}]},"image_url":"/recetas/receta-de-capuchino/portada.webp","gallery":[{"url":"/recetas/receta-de-capuchino/portada.webp","alt":"細かなミルクフォームとエスプレッソのクレマがある自家製カプチーノ"}],"seo":{"title":"自家製カプチーノ：エスプレッソと牛乳の手順 | Manual de Cocina","description":"計量したエスプレッソと牛乳で砂糖無添加のカプチーノ。55–60 °Cで細かく泡立てて提供する1杯分の案。","image_alt":"細かなミルクフォームとエスプレッソのクレマがある自家製カプチーノ","image_variants":["/recetas/receta-de-capuchino/portada-1x1.webp","/recetas/receta-de-capuchino/portada-4x3.webp","/recetas/receta-de-capuchino/portada-16x9.webp"],"faq":[{"q":"なぜコーヒー粉36 gではなくエスプレッソ36 gですか？","a":"抽出後の飲料の重さです。粉18 gからエスプレッソ36 gを得る1:2の比率を出発点にできます。かすは捨て、カップにも栄養計算にも加えません。"},{"q":"大きな泡ができるのはなぜですか？","a":"空気を入れすぎるか、先端が高すぎる場合があります。最初は柔らかく空気を入れ、次に渦を作り、最後にピッチャーを回します。55–60 °Cで止め、同じ牛乳を再度スチームにかけません。"},{"q":"保存や別の牛乳への変更はできますか？","a":"再加熱用に保存せず、すぐ提供する案です。乳糖不使用や植物性飲料では泡と栄養が変わります。計算は殺菌済み全乳の計量した全量に限ります。"}]},"published":false,"editorial_status":"draft","content_html":"<p>淹れたてのエスプレッソに、殺菌済み全乳と細かな泡を合わせます。ココア、チョコレート、生クリーム、添加糖は使わず、栄養計算の糖類は主に牛乳由来です。少量に対応するスチームノズル付きエスプレッソマシン、ピッチャー、温度計が必要です。</p><p>出来上がりは空気の量により約180–200 mlの1杯を提案します。準備5分、コーヒーと牛乳の加熱5分、マシンが使える状態になってから合計10分の推定です。マシンの予熱時間は別途必要になる場合があります。分量、時間、容量は調理試験待ちです。伝統的に必ず3等分する普遍的な比率とは主張しません。</p>"},{"id":"d732722e-4121-5c08-bd12-0637e49601cf","recipe_group_id":"cc320b67-294e-4420-b904-4bd3d12d4c1b","language":"pt","slug":"cappuccino-caseiro","public_path":"/pt/cappuccino-caseiro","source_url":null,"title":"Cappuccino caseiro com espresso e leite","excerpt":"Cappuccino sem açúcar adicionado com 36 g de espresso, 120 g de leite integral, espuma fina e temperatura controlada.","summary":"Espresso recém-preparado é combinado com leite integral pasteurizado e espuma fina. Sem cacau, chocolate, creme de leite ou açúcar adicionado; os açúcares calculados vêm principalmente do leite. É preciso máquina de espresso, vaporizador adequado a pequenas quantidades, jarra e termômetro.\n\nA proposta rende uma xícara de cerca de 180–200 ml conforme o ar incorporado. Estimam-se 5 minutos de preparo e 5 para café e leite, 10 no total depois que a máquina estiver pronta. O preaquecimento pode acrescentar tempo. Quantidades, tempos e volume aguardam teste de cozinha; não se afirma uma proporção tradicional universal de três partes iguais.","category":"Bebidas","category_slug":"bebidas","difficulty":"Média","course":"Bebida","cuisine":"Italiana, proposta caseira","prep_time_minutes":5,"cook_time_minutes":5,"total_time_minutes":10,"servings":1,"keywords":["cappuccino caseiro","espresso com leite","espuma de leite","receita cappuccino"],"ingredients":[{"name":"espresso recém-preparado","amount":"36","unit":"g de bebida, não de café moído","group":"Café"},{"name":"leite integral pasteurizado frio","amount":"120","unit":"g","group":"Leite"}],"steps":[{"title":"Prepare xícara, jarra e leite","content":"Use xícara de 180–200 ml, jarra pequena compatível com a quantidade de leite e termômetro limpo. Aqueça a xícara com água quente e esvazie completamente. Pese 120 g de leite frio a 4 °C ou menos na jarra; não deixe em temperatura ambiente. Siga o manual para preaquecimento e purga.","image_alt":"Jarra de leite frio ao lado de xícara vazia e máquina espresso","image_url":"/recetas/receta-de-capuchino/paso-01.webp"},{"title":"Prepare e pese o espresso","content":"Extraia espresso na xícara quente e pese 36 g de bebida fresca, sem o peso da xícara. Se a máquina não permite extração e vapor juntos, siga a sequência do manual sem deixar o café esperando muito. O peso é de líquido preparado, não de café seco. Não adicione açúcar ou cacau.","image_alt":"Espresso recém-extraído na xícara sob o porta-filtro","image_url":"/recetas/receta-de-capuchino/paso-02.webp"},{"title":"Texturize o leite sem ferver","content":"Purgue brevemente a lança apontando para a bandeja e afaste as mãos do vapor. Coloque a ponta perto da superfície dos 120 g de leite e abra o vapor para incorporar ar com um chiado suave, sem bolhas grandes. Mergulhe um pouco para criar redemoinho e pare quando o termômetro marcar 55–60 °C. Feche o vapor antes de retirar a jarra. Não ferva nem aqueça apenas por tempo fixo; a potência varia.","image_alt":"Lança texturizando leite em jarra metálica","image_url":"/recetas/receta-de-capuchino/paso-03.webp"},{"title":"Integre a espuma e limpe a lança","content":"Limpe logo a lança com pano limpo exclusivo e purgue conforme o manual, evitando queimaduras. Bata suavemente o fundo da jarra em um pano e gire o leite para unir espuma e líquido. Deve estar brilhante e fluido, sem bolhas grandes separadas. Não vaporize novamente leite já aquecido.","image_alt":"Leite texturizado brilhante após girar a jarra","image_url":"/recetas/receta-de-capuchino/paso-04.webp"},{"title":"Despeje e sirva imediatamente","content":"Despeje o leite sobre os 36 g de espresso em fio contínuo e aproxime a jarra no final para depositar espuma fina. Use todo o leite pesado para manter a estimativa; não precisa fazer desenho. Sirva logo e confira se a xícara não queima. O volume proposto de 180–200 ml depende da espuma. Não guarde para reaquecer: descarte sobra de leite texturizado e mantenha o leite frio não usado na geladeira.","image_alt":"Cappuccino pronto com espuma fina em xícara de cerâmica","image_url":"/recetas/receta-de-capuchino/paso-05.webp"}],"notes":"Contém leite e cafeína. Para espresso, pode começar com 18 g de café moído para obter 36 g de bebida, proporção 1:2, em cerca de 25–35 segundos; ajuste moagem e receita ao equipamento. Isso substitui o ingrediente espresso pronto, sem se somar a ele. A borra não é ingerida nem contada como 18 g de café comestível. Use dose adequada ao filtro e siga o manual. Se a jarra ou lança exige mais de 120 g de leite, o equipamento não serve para esta fórmula de uma xícara; não aqueça novamente a sobra. Leite sem lactose pode espumar, mas muda a nutrição. Bebida vegetal altera espuma, sabor e nutrientes e exige outra formulação; esta não é vegana. Açúcar, cacau e canela opcionais não estão incluídos. Não se promete cafeína exata: variedade, dose e extração influem. Mantenha o leite frio e use apenas pasteurizado. Vapor e xícara podem queimar; não encoste o termômetro na lança quente.","nutrition":{"fiber_g":0,"sodium_mg":57,"saturated_fat_g":2.3,"fat_g":4,"protein_g":3.8,"sugar_g":6.1,"carbs_g":6.4,"calories":76.4,"estimated":true,"serving_size":"1 xícara proposta com todo o leite pesado","source":"USDA FoodData Central — SR Legacy, April 2018 JSON","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Duas fichas USDA verificadas por FDC ID no arquivo oficial: 36 g de espresso pronto e 120 g de leite integral. Uma porção. Exclui borra, água para aquecer a xícara e ar incorporado. Supõe todo o leite pesado na xícara.","note":"Estimativa, não análise da bebida. Leite, extração e líquido deixado na jarra mudam o resultado. Volume, tempos e rendimento aguardam teste de cozinha. Sem açúcar adicionado ou cálculo de cafeína.","inputs":[{"fdc_id":171891,"fdc_description":"Beverages, coffee, brewed, espresso, restaurant-prepared","per_100g":{"fiber_g":0,"sodium_mg":14,"saturated_fat_g":0.092,"fat_g":0.18,"protein_g":0.12,"sugar_g":0,"carbs_g":1.67,"calories":9},"source_url":"https://fdc.nal.usda.gov/food-details/171891/nutrients","ingredient":"espresso recém-preparado","edible_grams":36},{"fdc_id":171265,"fdc_description":"Milk, whole, 3.25% milkfat, with added vitamin D","per_100g":{"fat_g":3.25,"sugar_g":5.05,"carbs_g":4.8,"calories":61,"saturated_fat_g":1.86,"fiber_g":0,"sodium_mg":43,"protein_g":3.15},"source_url":"https://fdc.nal.usda.gov/food-details/171265/nutrients","ingredient":"leite integral pasteurizado frio","edible_grams":120}]},"image_url":"/recetas/receta-de-capuchino/portada.webp","gallery":[{"url":"/recetas/receta-de-capuchino/portada.webp","alt":"Cappuccino caseiro com espuma fina e crema do espresso"}],"seo":{"title":"Cappuccino caseiro com espresso: passo a passo | Manual de Cocina","description":"Cappuccino sem açúcar adicionado com espresso e leite medidos. Texturize a 55–60 °C e sirva com espuma fina; proposta para uma xícara.","image_alt":"Cappuccino caseiro com espuma fina e crema do espresso","image_variants":["/recetas/receta-de-capuchino/portada-1x1.webp","/recetas/receta-de-capuchino/portada-4x3.webp","/recetas/receta-de-capuchino/portada-16x9.webp"],"faq":[{"q":"Por que 36 g de espresso e não de café moído?","a":"É o peso da bebida pronta. Pode começar com 18 g de café seco para obter 36 g de espresso, proporção 1:2. Descarte a borra; ela não vai à xícara nem ao cálculo nutricional."},{"q":"Por que a espuma tem bolhas grandes?","a":"Costuma entrar ar demais ou a ponta fica alta. Incorpore ar suavemente no início, depois faça redemoinho e gire a jarra. Pare a 55–60 °C e não vaporize o mesmo leite de novo."},{"q":"Posso guardar ou trocar o leite?","a":"Sirva imediatamente sem guardar para reaquecer. Leite sem lactose ou vegetal muda espuma e nutrição; o cálculo corresponde só ao leite integral pasteurizado e todo o peso medido."}]},"published":false,"editorial_status":"draft","content_html":"<p>Espresso recém-preparado é combinado com leite integral pasteurizado e espuma fina. Sem cacau, chocolate, creme de leite ou açúcar adicionado; os açúcares calculados vêm principalmente do leite. É preciso máquina de espresso, vaporizador adequado a pequenas quantidades, jarra e termômetro.</p><p>A proposta rende uma xícara de cerca de 180–200 ml conforme o ar incorporado. Estimam-se 5 minutos de preparo e 5 para café e leite, 10 no total depois que a máquina estiver pronta. O preaquecimento pode acrescentar tempo. Quantidades, tempos e volume aguardam teste de cozinha; não se afirma uma proporção tradicional universal de três partes iguais.</p>"}]$capuchino$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and recipe_group_id = g and language = 'es' and published = false and slug = 'receta-de-capuchino' and public_path = '/receta-de-capuchino') then
    raise exception 'Estado previo inesperado del grupo receta-de-capuchino';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x) or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path en receta-de-capuchino';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages en receta-de-capuchino';
  end if;
  update public.recipes r set
    title=x.title, excerpt=x.excerpt, summary=x.summary, ingredients=x.ingredients, steps=x.steps,
    category=x.category, prep_time_minutes=x.prep_time_minutes, cook_time_minutes=x.cook_time_minutes,
    total_time_minutes=x.total_time_minutes, servings=x.servings, image_url=x.image_url,
    content_html=coalesce(x.content_html,''), notes=x.notes, difficulty=x.difficulty, course=x.course,
    cuisine=x.cuisine, keywords=x.keywords, nutrition=x.nutrition, gallery=x.gallery, seo=x.seo,
    editorial_status='published', ready_at=ts, published=true
  from jsonb_populate_recordset(null::public.recipes,j) x where r.id=es_id and x.language='es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES de receta-de-capuchino afectó % filas', n; end if;
  insert into public.recipes (id,recipe_group_id,language,slug,public_path,source_url,title,excerpt,summary,ingredients,steps,category,prep_time_minutes,cook_time_minutes,total_time_minutes,servings,image_url,content_html,notes,difficulty,course,cuisine,keywords,nutrition,gallery,seo,editorial_status,ready_at,published)
  select x.id,g,x.language,x.slug,x.public_path,null,x.title,x.excerpt,x.summary,x.ingredients,x.steps,x.category,x.prep_time_minutes,x.cook_time_minutes,x.total_time_minutes,x.servings,x.image_url,coalesce(x.content_html,''),x.notes,x.difficulty,x.course,x.cuisine,x.keywords,x.nutrition,x.gallery,x.seo,'published',ts,true
  from jsonb_populate_recordset(null::public.recipes,j) x where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT de traducciones de receta-de-capuchino afectó % filas', n; end if;
  if (select count(*) from public.recipes where recipe_group_id=g and published and editorial_status='published' and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo receta-de-capuchino no quedó con 7 filas publicadas';
  end if;
  if (select count(distinct language) from public.recipes where recipe_group_id=g) <> 7 then
    raise exception 'El grupo receta-de-capuchino no quedó con 7 idiomas únicos';
  end if;
end
$pub$;
